#pragma once
// Static web assets compiled into the binary.
//
// forge_add_web(<target> DIR web) (or force_add_app(... WEB web)) turns every
// file under web/ into an Asset and registers it at startup; the HTTP server
// then serves them from memory. No files need to be deployed next to the binary.

#include <cstddef>
#include <string>
#include <string_view>
#include <vector>

namespace forge::web {

struct Asset {
    const char* path;            ///< URL path, e.g. "/index.html"
    const unsigned char* data;
    std::size_t size;
};

/// Register assets (called by the code generated by forge_add_web()).
void register_assets(const Asset* assets, std::size_t count);

/// All assets registered by the application.
std::vector<Asset> registered_assets();

/// Built-in dashboard assets, served under /forge/.
std::vector<Asset> builtin_assets();

/// MIME type for a path, based on its extension.
std::string mime_type(std::string_view path);

}  // namespace forge::web
